#include <bits/stdc++.h>
using namespace std;
using ll=long long;
const int B=1e6;
const int mod1=998244353;
const int mod2=1e9+7;

ll n, count_total;
vector<int> v[10];
int sum[10], result, total_count;

inline int mod_value(ll x) {
    return (x % mod1 + mod1) % mod1;
}

void build_sequences(int depth, ll num) {
    ++count_total;
    v[depth].push_back(mod_value(count_total - num));
    if (depth == 6) return;
    for (int digit=0; digit<=9; ++digit) {
        build_sequences(depth+1, num*10+digit);
    }
}

void compute_results(int depth, ll num) {
    if (num > n) return;
    if (depth >= 1) {
        if (num*B > n/10 && (num+1)*B -1 <= n) {
            int factor=1;
            for (int i=0; i<=6; ++i, factor*=10) {
                int w=mod_value(count_total - factor*num);
                int pos=lower_bound(v[i].begin(), v[i].end(), mod_value(mod1 - w)) - v[i].begin();
                result= (result + 1LL*w*v[i].size() + sum[i] - 1LL*mod1*((int)v[i].size() - pos))%mod2;
            }
            count_total+=total_count;
            return;
        }
        ++count_total;
        result= (result + mod_value(count_total - num))%mod2;
    }
    for (int digit= (depth==0?1:0); digit<=9; ++digit) {
        compute_results(depth+1, num*10+digit);
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin>>n;
    build_sequences(0,0);
    for (int i=0; i<=6; ++i) {
        sort(v[i].begin(), v[i].end());
        sum[i]=accumulate(v[i].begin(), v[i].end(), 0LL)%mod2;
    }
    total_count= count_total;
    count_total=0;
    compute_results(0,0);
    cout<<(result+mod2)%mod2<<'\n';
    return 0;
}
